package com.aoo.bcg.common.lifecycle;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
/** LIFO scope for locks, MDC entries, temporary files and other non-JDBC resources. */
public final class ResourceScope implements AutoCloseable{private record Cleanup(String name,CheckedCleanup action){}private final Deque<Cleanup>cleanups=new ArrayDeque<>();private final AtomicBoolean closed=new AtomicBoolean();public synchronized ResourceScope defer(String name,CheckedCleanup cleanup){if(closed.get())throw new IllegalStateException("resource scope already closed");if(name==null||name.isBlank()||cleanup==null)throw new IllegalArgumentException("named cleanup required");cleanups.push(new Cleanup(name,cleanup));return this;}@Override public synchronized void close()throws Exception{if(!closed.compareAndSet(false,true))return;Exception aggregate=null;while(!cleanups.isEmpty())try{cleanups.pop().action().run();}catch(Exception failure){if(aggregate==null)aggregate=new Exception("resource cleanup failed",failure);else aggregate.addSuppressed(failure);}if(aggregate!=null)throw aggregate;}@FunctionalInterface public interface CheckedCleanup{void run()throws Exception;}}
